UPDATE employees SET service_records = jsonb_set(service_records, '{0, designation}', '"MSWDO"') || jsonb_set(service_records, '{0, station}', '"Municipal Social Welfare and Development Office"') || jsonb_set(service_records, '{0, salary}', '"80648.00"') || jsonb_set(service_records, '{0, annual_salary}', '"967776.00"') WHERE surname ILIKE '%Talaban%' AND first_name ILIKE '%Babelyn%';
